// 1. Ignora mensagens de erro ou payloads inválidos
if (msg.error || typeof msg.payload !== "object" || msg.payload === null) {
    return null; // Interrompe o fluxo desta mensagem sem gerar erro
}

// 2. Atualiza apenas as chaves válidas (ignora valores null ou undefined)
for (let chave in msg.payload) {
    let valor = msg.payload[chave];
    if (valor !== null && valor !== undefined) {
        flow.set(chave, valor);
    }
}

// 3. Monta o JSON estruturado
let dados = {
    PN2594: {
        PRESSAO: flow.get("PN2594_PRESSAO"),
        SP1: flow.get("PN2594_SP1"),
        OUT_2: flow.get("PN2594_OUT_2")
    },
    DP2200: {
        CORRENTE: flow.get("DP2200_CORRENTE"),
        STATUS: flow.get("DP2200_STATUS")
    },
    LT3023: {
        NIVEL: flow.get("LT3023_NIVEL"),
        TEMPERATURA: flow.get("LT3023_TEMPERATURA")
    },
    LMT100: {
        CAPACITANCIA: flow.get("LMT100_CAPACITANCIA"),
        NA: flow.get("LMT100_NA"),
        NF: flow.get("LMT100_NF")
    },
    ENTRADAS_CLP: {
        STATUS_B_EMER: flow.get("STATUS_B_EMER"),
        STATUS_B_LIGA: flow.get("STATUS_B_LIGA"),
        STATUS_B_DESLIGA: flow.get("STATUS_B_DESLIGA"),
        STATUS_B_RESET: flow.get("STATUS_B_RESET"),
        STATUS_DO0_INV: flow.get("STATUS_DO0_INV"),
        STATUS_DO2_INV: flow.get("STATUS_DO2_INV")
    },
    SAIDAS_CLP: {
        LED_B_LIGA: flow.get("LED_B_LIGA"),
        LED_B_DESLIGA: flow.get("LED_B_DESLIGA"),
        LED_B_RESET: flow.get("LED_B_RESET"),
        ACIONA_VALVULA: flow.get("ACIONA_VALVULA"),
        RELE_INTERFACE_2: flow.get("RELE_INTERFACE_2"),
        RELE_INTERFACE_3: flow.get("RELE_INTERFACE_3"),
        DI0_INV: flow.get("DI0_INV"),
        DI2_INV: flow.get("DI2_INV")
    }
};

// 4. Verifica se alguma variável ainda não recebeu o primeiro valor (undefined)
// Se ainda estiver aguardando algum nó comunicar na inicialização, não envia o JSON
for (let grupo in dados) {
    for (let tag in dados[grupo]) {
        if (dados[grupo][tag] === undefined) {
            return null;
        }
    }
}

msg.payload = dados;
return msg;

const d = msg.payload;
const toNum = (val) => (val === true || val === 1) ? 1 : 0;

// 1. Saída 1: Sensores Analógicos
const msgAnalogicos = {
    measurement: "sensores_analogicos",
    payload: [
        {
            nivel: Number(d.LT3023.NIVEL),
            temperatura: Number(d.LT3023.TEMPERATURA),
            corrente: Number(d.DP2200.CORRENTE),
            dp2200_status: Number(d.DP2200.STATUS),
            pressao: Number(d.PN2594.PRESSAO),
            capacitancia: Number(d.LMT100.CAPACITANCIA)
        },
        { bancada: "didatica_01" }
    ]
};

// 2. Saída 2: Sensores Digitais
const msgDigitaisSensores = {
    measurement: "sensores_digitais",
    payload: [
        {
            pn2594_sp1: toNum(d.PN2594.SP1),
            pn2594_out2: toNum(d.PN2594.OUT_2),
            lmt100_na: toNum(d.LMT100.NA),
            lmt100_nf: toNum(d.LMT100.NF)
        },
        { bancada: "didatica_01" }
    ]
};

// 3. Saída 3: Entradas e Saídas do CLP
const msgCLP = {
    measurement: "clp_io",
    payload: [
        {
            // Entradas
            status_emer: toNum(d.ENTRADAS_CLP.STATUS_B_EMER),
            status_liga: toNum(d.ENTRADAS_CLP.STATUS_B_LIGA),
            status_desliga: toNum(d.ENTRADAS_CLP.STATUS_B_DESLIGA),
            status_reset: toNum(d.ENTRADAS_CLP.STATUS_B_RESET),
            status_do0_inv: toNum(d.ENTRADAS_CLP.STATUS_DO0_INV),
            status_do2_inv: toNum(d.ENTRADAS_CLP.STATUS_DO2_INV),
            // Saídas
            led_liga: toNum(d.SAIDAS_CLP.LED_B_LIGA),
            led_desliga: toNum(d.SAIDAS_CLP.LED_B_DESLIGA),
            led_reset: toNum(d.SAIDAS_CLP.LED_B_RESET),
            aciona_valvula: toNum(d.SAIDAS_CLP.ACIONA_VALVULA),
            rele_2: toNum(d.SAIDAS_CLP.RELE_INTERFACE_2),
            rele_3: toNum(d.SAIDAS_CLP.RELE_INTERFACE_3),
            di0_inv: toNum(d.SAIDAS_CLP.DI0_INV),
            di2_inv: toNum(d.SAIDAS_CLP.DI2_INV)
        },
        { bancada: "didatica_01" }
    ]
};

return [msgAnalogicos, msgDigitaisSensores, msgCLP];

// Gera um número inteiro aleatório de 0 a 20
const valorAleatorio = Math.floor(Math.random() * 21);

// Define um measurement exclusivo de teste (para não sujar seus dados reais)
msg.measurement = "teste_simulacao";

// Formato padrão esperado pelo nó influxdb out: [ { fields }, { tags } ]
msg.payload = [
    {
        valor_teste: valorAleatorio
    },
    {
        bancada: "simulacao_casa"
    }
];

return msg;
